  duration: number;
  dependsOn: string[];
};

type Input = { tasks: Task[] };

type Plan = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

