  let parsed: unknown;
  try { parsed = JSON.parse(text); } catch { fail("Invalid JSON input."); }
  console.log(JSON.stringify(plan(validate(parsed))));
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});

